import { Outlet, Link, useLocation, useNavigate } from "react-router-dom";
import {
  LayoutDashboard,
  Users,
  ScanLine,
  CreditCard,
  Activity,
  ToggleLeft,
  Puzzle,
  MessageSquare,
  ScrollText,
  ArrowLeft,
  ChevronRight,
  ChevronDown,
  ExternalLink,
  LogOut,
  Settings,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/ui/sidebar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useAuth } from "@/contexts/AuthContext";
import { cn } from "@/lib/utils";

interface AdminNavItem {
  title: string;
  href: string;
  icon: React.ElementType;
}

const NAV_ITEMS: AdminNavItem[] = [
  { title: "Dashboard", href: "/admin", icon: LayoutDashboard },
  { title: "Users", href: "/admin/users", icon: Users },
  { title: "Scans", href: "/admin/scans", icon: ScanLine },
  { title: "Billing", href: "/admin/billing", icon: CreditCard },
  { title: "System", href: "/admin/system", icon: Activity },
  { title: "Feature Flags", href: "/admin/flags", icon: ToggleLeft },
  { title: "Integrations", href: "/admin/integrations", icon: Puzzle },
  { title: "Support", href: "/admin/support", icon: MessageSquare },
  { title: "Audit Log", href: "/admin/audit-log", icon: ScrollText },
];

function getSidebarDefaultOpen(): boolean {
  const match =
    typeof document !== "undefined"
      ? document.cookie
          .split(";")
          .find((c) => c.trim().startsWith("sidebar:state="))
      : undefined;
  if (!match) return true;
  return match.split("=")[1]?.trim() === "true";
}

export function AdminLayout() {
  const location = useLocation();
  const navigate = useNavigate();
  const { profile, signOut } = useAuth();

  const displayName = profile?.full_name ?? "Admin";
  const initials = displayName
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);

  const isActive = (href: string) => {
    if (href === "/admin") return location.pathname === "/admin";
    return location.pathname.startsWith(href);
  };

  const handleLogout = async () => {
    await signOut();
    navigate("/login", { replace: true });
  };

  const pageTitle =
    location.pathname === "/admin"
      ? "Dashboard"
      : location.pathname
          .split("/")
          .filter(Boolean)
          .slice(1)
          .map((s) =>
            s
              .split("-")
              .map((w) => w[0].toUpperCase() + w.slice(1))
              .join(" ")
          )
          .join(" / ");

  return (
    <SidebarProvider defaultOpen={getSidebarDefaultOpen()}>
      <div className="h-screen flex w-full overflow-hidden bg-background">
        {/* Admin Sidebar — same shadcn components + CSS as user sidebar */}
        <Sidebar collapsible="icon" className="border-r-0">
          <SidebarHeader className="px-4 py-5 group-data-[collapsible=icon]:px-2 group-data-[collapsible=icon]:py-4 group-data-[collapsible=icon]:items-center">
            <div className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-full">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-primary shrink-0">
                <ScanLine className="h-3.5 w-3.5 text-white" />
              </div>
              <div className="flex flex-col leading-tight min-w-0 group-data-[collapsible=icon]:hidden">
                <span className="text-sm font-semibold text-white tracking-tight truncate">
                  ConvertScan
                </span>
                <span className="text-2xs text-white/30 font-medium uppercase tracking-wider">
                  Admin
                </span>
              </div>
            </div>
          </SidebarHeader>

          <SidebarContent className="px-2 group-data-[collapsible=icon]:px-1">
            <SidebarGroup>
              <SidebarGroupContent>
                <SidebarMenu className="space-y-0.5">
                  {NAV_ITEMS.map((item) => {
                    const active = isActive(item.href);
                    return (
                      <SidebarMenuItem key={item.href}>
                        <SidebarMenuButton
                          asChild
                          tooltip={item.title}
                          isActive={active}
                          className={cn(
                            "h-10 transition-colors duration-150 relative",
                            active
                              ? "bg-white/10 text-white before:absolute before:left-0 before:top-2 before:bottom-2 before:w-[2px] before:rounded-full before:bg-primary"
                              : "text-sidebar-foreground hover:bg-white/5 hover:text-white/80"
                          )}
                        >
                          <Link to={item.href}>
                            <item.icon
                              className={cn(
                                "h-[18px] w-[18px] shrink-0",
                                active ? "text-white" : "text-white/55"
                              )}
                            />
                            <span className="text-sm font-medium">
                              {item.title}
                            </span>
                          </Link>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    );
                  })}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          </SidebarContent>

          <SidebarFooter className="p-3 group-data-[collapsible=icon]:p-2 group-data-[collapsible=icon]:items-center">
            <SidebarMenu>
              <SidebarMenuItem>
                <SidebarMenuButton
                  asChild
                  tooltip="Back to App"
                  className="h-10 text-white/40 hover:text-white/70 hover:bg-white/5 transition-colors"
                >
                  <Link to="/dashboard">
                    <ArrowLeft className="h-[18px] w-[18px] shrink-0 text-white/40" />
                    <span className="text-sm">Back to App</span>
                  </Link>
                </SidebarMenuButton>
              </SidebarMenuItem>
            </SidebarMenu>
          </SidebarFooter>
        </Sidebar>

        {/* Main content */}
        <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
          {/* Admin top bar — same height + styling as user TopBar */}
          <header className="flex h-[60px] items-center justify-between border-b border-border/40 bg-background/80 backdrop-blur-sm px-4 shrink-0">
            <div className="flex items-center gap-3">
              <SidebarTrigger className="text-muted-foreground hover:text-foreground transition-colors" />
              <Badge className="bg-primary/10 text-primary border-primary/20 text-xs font-medium px-2 py-0.5">
                Admin
              </Badge>
              <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40" />
              <span className="text-sm font-medium text-foreground">
                {pageTitle}
              </span>
            </div>

            <div className="flex items-center gap-2">
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <button
                    type="button"
                    className="flex items-center gap-2 rounded-lg px-2.5 py-1.5 border border-transparent hover:border-border/60 hover:bg-muted/50 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <Avatar className="h-7 w-7">
                      {profile?.avatar_url && (
                        <AvatarImage
                          src={profile.avatar_url}
                          alt={displayName}
                        />
                      )}
                      <AvatarFallback className="bg-primary/10 text-2xs font-medium text-primary">
                        {initials}
                      </AvatarFallback>
                    </Avatar>
                    <div className="hidden sm:flex flex-col items-start leading-tight">
                      <span className="text-xs font-medium text-foreground">
                        {displayName.split(" ")[0]}
                      </span>
                      <span className="text-2xs text-muted-foreground capitalize">
                        {profile?.role?.replace("_", " ") ?? "admin"}
                      </span>
                    </div>
                    <ChevronDown className="hidden sm:block h-3.5 w-3.5 text-muted-foreground/60" />
                  </button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-56 p-0">
                  <div className="flex items-center gap-2.5 px-3 py-2.5 border-b border-border/60">
                    <Avatar className="h-8 w-8 shrink-0">
                      {profile?.avatar_url && (
                        <AvatarImage
                          src={profile.avatar_url}
                          alt={displayName}
                        />
                      )}
                      <AvatarFallback className="bg-primary/10 text-xs font-medium text-primary">
                        {initials}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-foreground truncate">
                        {displayName}
                      </p>
                      <p className="text-xs text-muted-foreground truncate">
                        {profile?.email ?? ""}
                      </p>
                    </div>
                  </div>
                  <div className="py-1">
                    <DropdownMenuItem
                      onClick={() => navigate("/settings")}
                      className="gap-2 px-3 py-2 cursor-pointer"
                    >
                      <Settings className="h-3.5 w-3.5 text-muted-foreground" />
                      <span>Settings</span>
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => navigate("/dashboard")}
                      className="gap-2 px-3 py-2 cursor-pointer"
                    >
                      <ExternalLink className="h-3.5 w-3.5 text-muted-foreground" />
                      <span>View App</span>
                    </DropdownMenuItem>
                  </div>
                  <DropdownMenuSeparator />
                  <div className="py-1">
                    <DropdownMenuItem
                      onClick={handleLogout}
                      className="gap-2 px-3 py-2 cursor-pointer text-destructive focus:text-destructive focus:bg-destructive/10"
                    >
                      <LogOut className="h-3.5 w-3.5" />
                      <span>Log out</span>
                    </DropdownMenuItem>
                  </div>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </header>

          {/* Page content */}
          <main className="flex-1 p-4 md:p-6 lg:p-8 bg-background overflow-auto">
            <div className="mx-auto max-w-[1140px]">
              <Outlet />
            </div>
          </main>
        </div>
      </div>
    </SidebarProvider>
  );
}

